  "좌타해결사": { "좌": "좌타해결사(좌타)", "양": "좌타해결사(양타)", "우": "좌타해결사(우타)" },
  "좌승사자": { "좌": "좌승사자(좌투)", "우": "좌승사자(우투)" },
