  var fa = !!pl.isFa && !!FA_CARDS[pl.cardType] && other;
  var wc = !!pl.isWildcard && !!WILDCARD_CARDS[pl.cardType] && other;
  if (fa === !!pl.isFa && wc === !!pl.isWildcard) return pl;
  return Object.assign({}, pl, { isFa: fa, isWildcard: wc });
